function getBooleanColumnText(column) {
    var caption = column && column.caption ? column.caption : column && column.name ? column.name : "";
    var baseText = caption.replace(/([a-z])([A-Z])/g, "$1 $2").replace(/^is\s+/i, "").trim();

    if (baseText.toLowerCase() === "active") {
        return {
            trueText: "Active",
            falseText: "Not Active"
        };
    }

    return {
        trueText: baseText || "Yes",
        falseText: baseText ? "Not " + baseText : "No"
    };
}

function applyBooleanColumnOptions(item, column) {
    if (!item || !column || !column.type || column.type.toLowerCase() !== "boolean") {
        return item;
    }

    var booleanText = getBooleanColumnText(column);
    item.trueText = booleanText.trueText;
    item.falseText = booleanText.falseText;
    item.headerFilter = {
        dataSource: [
            { text: booleanText.trueText, value: true },
            { text: booleanText.falseText, value: false }
        ]
    };

    return item;
}

function prepareBooleanFilterEditor(e) {
    if (!e || e.parentType !== "filterRow" || !e.component || !e.dataField) {
        return;
    }

    var column = e.component.columnOption(e.dataField);
    if (!column) {
        return;
    }

    if (column.dataType === "datetime") {
        e.editorOptions.type = "datetime";
        e.editorOptions.displayFormat = "yyyy-MM-dd HH:mm:ss";
        e.editorOptions.useMaskBehavior = true;
        e.editorOptions.showAnalogClock = true;
        return;
    }

    if (column.dataType !== "boolean") {
        return;
    }

    var trueText = column.trueText || "Yes";
    var falseText = column.falseText || "No";
    var selectedValue = e.value;

    e.editorOptions.dataSource = [
        { value: null, text: "(All)" },
        { value: true, text: trueText },
        { value: false, text: falseText }
    ];
    e.editorOptions.valueExpr = "value";
    e.editorOptions.displayExpr = "text";
    e.editorOptions.itemTemplate = function (data) {
        if (!data || data.value === null) {
            return $('<div>').addClass('aims-boolean-filter-option aims-boolean-filter-option-all').text('(All)');
        }

        var isSelected = selectedValue === data.value;
        var wrapper = $('<div>').addClass('aims-boolean-filter-option');
        $('<span>')
            .addClass('aims-boolean-filter-check')
            .toggleClass('is-checked', isSelected)
            .append($('<span>').addClass('aims-boolean-filter-checkmark'))
            .appendTo(wrapper);
        $('<span>').addClass('aims-boolean-filter-text').text(data.text).appendTo(wrapper);

        return wrapper;
    };
    e.editorOptions.onSelectionChanged = function (args) {
        selectedValue = args && args.selectedItem ? args.selectedItem.value : null;
    };
}

function loadDxDataGrid(componentId, controllerName, actionName, columns, actions) {
    var dataColumns = renderColumns(controllerName, columns, actions, "", "");

    $(() => {
        //JS PDF
        window.jsPDF = window.jspdf.jsPDF;

        function isNotEmpty(value) {
            return value !== undefined && value !== null && value !== '';
        }

        const store = new DevExpress.data.CustomStore({
            key: columns[0].name,
            load(loadOptions) {
                const deferred = $.Deferred();
                const args = {};
                [
                    'skip',
                    'take',
                    'requireTotalCount',
                    'requireGroupCount',
                    'sort',
                    'filter',
                    'totalSummary',
                    'group',
                    'groupSummary',
                ].forEach((i) => {
                    if (i in loadOptions && isNotEmpty(loadOptions[i])) {
                        args[i] = JSON.stringify(loadOptions[i]);
                    }
                });
                $.ajax({
                    url: url,
                    dataType: 'json',
                    contentType: "application/json; charset=utf-8",
                    data: args,
                    success(result) {
                        deferred.resolve(result.data, {
                            totalCount: result.totalCount,
                            summary: result.summary,
                            groupCount: result.groupCount,
                        });
                    }
                });

                return deferred.promise();
            },
        });

        var url = baseUrl + "/" + controllerName + "/" + actionName;

        const dataGrid = $('#' + componentId).dxDataGrid({
            dataSource: store,
            showColumnLines: true,
            showRowLines: true,
            rowAlternationEnabled: true,
            showBorders: true,
            filterRow: {
                visible: true,
            },
            headerFilter: {
                visible: true,
            },
            groupPanel: {
                visible: true,
            },
            remoteOperations: true,
            paging: {
                pageSize: 10,
            },
            showBorders: true,
            columnAutoWidth: true,
            allowColumnResizing: true,
            scrolling: {
                mode: "standard",
                useNative: true,
                showScrollbar: "onScroll"
            },
            loadPanel: {
                enabled: true,
                text: "Loading data..."
            },
            pager: {
                visible: true,
                showPageSizeSelector: true,
                allowedPageSizes: [10, 50, 100],
                showNavigationButtons: true,
                showInfo: true
            },
            onEditorPreparing: prepareBooleanFilterEditor,
            onContentReady: function (e) {
                var index = DevExpress.localization.formatNumber(e.component.pageIndex() + 1, ",##0.###");
                var count = DevExpress.localization.formatNumber(e.component.pageCount(), ",##0.###");
                var total = DevExpress.localization.formatNumber(e.component.totalCount(), ",##0.###");
                e.component.option("pager.infoText", "Page " + index + " of " + count + " (" + total + " items)");
            },
            columns: dataColumns,
        }).dxDataGrid('instance');

        $('#export_pdf_dxgrid').dxButton({
            onClick: function (e) {
                const doc = new jsPDF();
                DevExpress.pdfExporter.exportDataGrid({
                    jsPDFDocument: doc,
                    component: dataGrid
                }).then(function () {
                    doc.save('Export.pdf');
                });
                e.cancel = true;
            }
        });

        $('#export_excel_dxgrid').dxButton({
            onClick: function (e) {
                const workbook = new ExcelJS.Workbook();
                const worksheet = workbook.addWorksheet('Sheet1');

                DevExpress.excelExporter.exportDataGrid({
                    component: dataGrid,
                    worksheet,
                    autoFilterEnabled: true,
                }).then(() => {
                    workbook.xlsx.writeBuffer().then((buffer) => {
                        saveAs(new Blob([buffer], { type: 'application/octet-stream' }), 'Export.xlsx');
                    });
                });
                e.cancel = true;
            }
        });
    });
}

