// Restored from the original PTK source. This variant is still used by
// Transfer Type to render its nested approver grid.
function loadDxDataGridMasterDetails(componentId, controllerName, actionName, columns, actions, actionNameDetail, columnDetails, actionDetails, detailTitle, fkParentId) {
    var dataColumns = renderColumns(controllerName, columns, actions, null, null);
    var detailColumns = renderColumns(controllerName, columnDetails, actionDetails, null, null);
    var url = baseUrl + "/" + controllerName + "/" + actionName;
    var detailUrl = baseUrl + "/" + controllerName + "/" + actionNameDetail;

    function createRemoteStore(storeUrl, keyName) {
        return new DevExpress.data.CustomStore({
            key: keyName,
            load: function (loadOptions) {
                var deferred = $.Deferred();
                var args = {};
                [
                    'skip', 'take', 'requireTotalCount', 'requireGroupCount',
                    'sort', 'filter', 'totalSummary', 'group', 'groupSummary'
                ].forEach(function (optionName) {
                    var value = loadOptions[optionName];
                    if (value !== undefined && value !== null && value !== '') {
                        args[optionName] = JSON.stringify(value);
                    }
                });

                $.ajax({
                    url: storeUrl,
                    dataType: 'json',
                    contentType: 'application/json; charset=utf-8',
                    data: args,
                    success: function (result) {
                        deferred.resolve(result.data, {
                            totalCount: result.totalCount,
                            summary: result.summary,
                            groupCount: result.groupCount
                        });
                    },
                    error: function (xhr) {
                        deferred.reject(xhr.responseJSON && xhr.responseJSON.message
                            ? xhr.responseJSON.message
                            : 'Unable to load data.');
                    }
                });

                return deferred.promise();
            }
        });
    }

    $(() => {
        if (window.jspdf && window.jspdf.jsPDF) {
            window.jsPDF = window.jspdf.jsPDF;
        }

        var dataGrid = $('#' + componentId).dxDataGrid({
            dataSource: createRemoteStore(url, columns[0].name),
            showColumnLines: true,
            showRowLines: true,
            rowAlternationEnabled: true,
            showBorders: true,
            wordWrapEnabled: true,
            columnAutoWidth: true,
            allowColumnResizing: true,
            remoteOperations: true,
            filterRow: { visible: true },
            headerFilter: { visible: true },
            groupPanel: { visible: true },
            paging: { pageSize: 10 },
            scrolling: { mode: 'standard', useNative: true },
            loadPanel: { enabled: true },
            pager: {
                visible: true,
                showPageSizeSelector: true,
                allowedPageSizes: [10, 50, 100],
                showNavigationButtons: true,
                showInfo: true
            },
            onContentReady: function (e) {
                var index = DevExpress.localization.formatNumber(e.component.pageIndex() + 1, ',##0.###');
                var count = DevExpress.localization.formatNumber(e.component.pageCount(), ',##0.###');
                var total = DevExpress.localization.formatNumber(e.component.totalCount(), ',##0.###');
                e.component.option('pager.infoText', 'Page ' + index + ' of ' + count + ' (' + total + ' items)');
            },
            columns: dataColumns,
            masterDetail: {
                enabled: true,
                autoExpandAll: false,
                template: function (container, options) {
                    $('<div>')
                        .addClass('master-detail-caption')
                        .text(detailTitle)
                        .appendTo(container);

                    $('<div>').dxDataGrid({
                        dataSource: createRemoteStore(
                            detailUrl + '?' + encodeURIComponent(fkParentId) + '=' + encodeURIComponent(options.key),
                            columnDetails[0].name
                        ),
                        columnAutoWidth: true,
                        showBorders: true,
                        wordWrapEnabled: true,
                        columns: detailColumns
                    }).appendTo(container);
                }
            }
        }).dxDataGrid('instance');

        $('#export_pdf_dxgrid').dxButton({
            onClick: function (e) {
                if (!window.jsPDF) return;
                var doc = new window.jsPDF();
                DevExpress.pdfExporter.exportDataGrid({
                    jsPDFDocument: doc,
                    component: dataGrid
                }).then(function () { doc.save('Export.pdf'); });
                e.cancel = true;
            }
        });

        $('#export_excel_dxgrid').dxButton({
            onClick: function (e) {
                var workbook = new ExcelJS.Workbook();
                var worksheet = workbook.addWorksheet('Sheet1');
                DevExpress.excelExporter.exportDataGrid({
                    component: dataGrid,
                    worksheet: worksheet,
                    autoFilterEnabled: true
                }).then(function () {
                    return workbook.xlsx.writeBuffer();
                }).then(function (buffer) {
                    saveAs(new Blob([buffer], { type: 'application/octet-stream' }), 'Export.xlsx');
                });
                e.cancel = true;
            }
        });
    });
}

