function renderColumns(controllerName, columns, actions, fkId, page) {
    var dataColumns = [];
    if (actions.length > 0) {
        var pageQuery = "";
        if (typeof fkId !== "undefined" && typeof page !== "undefined") {
            pageQuery = "?fkId=" + fkId + "&page=" + page;
        }

        var baseControllerName = baseUrl + "/" + controllerName;
        var actionCustom = {
            dataField: "Actions",
            type: "buttons",
            allowGrouping: false,
            allowSorting: false,
            cellTemplate(container, item) {
                const { data } = item;
                var appendDiv = $('<div>');
                for (let i = 0; i < actions.length; i++) {
                    var template = templates.filter(p => p.name == actions[i]);
                    if (template.length > 0) {
                        var urlAction = baseControllerName + '/' + actions[i] + '/' + data.Id + pageQuery;
                        var htmlRender = "";
                        if (actions[i].toLowerCase() == "delete" || actions[i].toLowerCase() == "deletedetail") {
                            htmlRender =
                                '\
                                    <a style="margin-right: 5px !important;" class="' + template[0].class_button + '" title="' + template[0].title + '" onclick="deleteData(\'' + urlAction + '\');">\
                                        '+ template[0].class_icon + ' \
                                    </a>';
                        }
                        else if (actions[i].toLowerCase() == "testreminder") {
                            htmlRender =
                                '\
                                    <button type="button" style="margin-right: 5px !important;" class="' + template[0].class_button + '" title="' + template[0].title + '" aria-label="' + template[0].title + '" onclick="testReminder(\'' + urlAction + '\', this);">\
                                        '+ template[0].class_icon + ' \
                                    </button>';
                        }
                        else if (actions[i].toLowerCase() == "addsender") {
                            htmlRender =
                                '\
                                    <button type="button" style="margin-right: 5px !important;" class="' + template[0].class_button + '" title="' + template[0].title + '" data-bs-toggle="modal" data-bs-target="#formDataSender" onclick="getDataReceiver(\'' + data.Id + '\');">\
                                        '+ template[0].class_icon + ' \
                                    </button>';
                        }
                        else {
                            htmlRender =
                                '\
                                    <a style="margin-right: 5px !important;" href="'+ urlAction + '" class="' + template[0].class_button + '" title="' + template[0].title + '">\
                                        '+ template[0].class_icon + ' \
                                    </a>';
                        }

                        appendDiv = appendDiv.append($(htmlRender))
                    }
                }
                appendDiv = appendDiv.appendTo(container);
            }
        };

        dataColumns.push(actionCustom);
    }

    var key = "";
    for (let x = 0; x < columns.length; x++) {
        if (x == 0) {
            key = columns[x].name;
        }
        else {
            var item = {};

            item = {
                dataField: columns[x].name,
                dataType: columns[x].type,
            };
            item = applyBooleanColumnOptions(item, columns[x]);

            if (columns[x].name.toLowerCase() == "fileattachment") {
                item = {
                    dataField: columns[x].name,
                    dataType: columns[x].type,
                    cellTemplate(container, items) {
                        const { data } = items;
                        var appendDiv = $('<div>');
                        var htmlRender = "";
                        if (data.FileAttachment != "" && data.FileAttachment != null && data.FileAttachment != undefined) {
                            var urlActionDownload = baseUrl + '/Document/DownloadFile?fileName=' + data.FileAttachment;
                            htmlRender =
                                '\
                                        <center><a target = "_blank"  style="margin-right: 5px !important;" href="'+ urlActionDownload + '" class="btn btn-sm btn-round btn-icon btn-primary waves-effect waves-float waves-light" title="Download">\
                                           <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="feather feather-download"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"></path><polyline points="7 10 12 15 17 10"></polyline><line x1="12" y1="15" x2="12" y2="3"></line></svg> \
                                        </a></center>';
                        }
                        appendDiv = appendDiv.append($(htmlRender)).appendTo(container);
                    }
                };
            }


            if (columns[x].name.toLowerCase() == "approvalstatus") {
                item = {
                    dataField: columns[x].name,
                    dataType: columns[x].type,
                    cellTemplate(container, items) {
                        const { data } = items;
                        var appendDiv = $('<div>');
                        var htmlRender = "";
                        if (data.ApprovalStatus != "") {
                            var st = data.ApprovalStatus.toUpperCase();
                            var stCls = "badge-light-secondary";
                            if (st.indexOf("COMPLET") >= 0) { stCls = "badge-light-success"; }
                            else if (st.indexOf("APPROV") >= 0) { stCls = "badge-light-info"; }
                            else if (st.indexOf("REVIS") >= 0) { stCls = "badge-light-danger"; }
                            else if (st.indexOf("CANCEL") >= 0) { stCls = "badge-light-dark"; }
                            else if (st.indexOf("REQUEST") >= 0) { stCls = "badge-light-warning"; }
                            else if (st.indexOf("DRAFT") >= 0) { stCls = "badge-light-secondary"; }
                            htmlRender = '<span class="badge rounded-pill ' + stCls + '" text-capitalized="">' + st + '</span>';
                        }
                        appendDiv = appendDiv.append($(htmlRender)).appendTo(container);
                    }
                };
            }


            if (columns[x].name.toLowerCase() == "type") {
                item = {
                    dataField: columns[x].name,
                    dataType: columns[x].type,
                    cellTemplate(container, items) {
                        const { data } = items;
                        var typeValue = data.Type == null ? "" : String(data.Type).trim();

                        if (typeValue !== "") {
                            var normalizedType = typeValue.replace(/_/g, " ").toUpperCase();
                            var typeModifier = normalizedType
                                .toLowerCase()
                                .replace(/[^a-z0-9]+/g, "-")
                                .replace(/^-+|-+$/g, "");

                            $('<span>', {
                                class: 'badge rounded-pill aims-type-badge aims-type-badge--' + (typeModifier || 'default'),
                                text: normalizedType
                            }).appendTo(container);
                        }
                    }
                };
            }

            if (columns[x].type.toLowerCase() == "date") {
                item.format = "yyyy-MM-dd";
            }

            if (columns[x].type.toLowerCase() == "datetime") {
                item.format = "yyyy-MM-dd HH:mm";
            }

            if (columns[x].type.toLowerCase() == "currency" || columns[x].type.toLowerCase() == "number" || columns[x].type.toLowerCase() == "double") {
                item.format = ",##0.##";
            }

            if (columns[x].caption !== undefined && columns[x].caption !== null && columns[x].caption !== '') {
                item.caption = columns[x].caption;
            }

            if (columns[x].sortIndex !== undefined && columns[x].sortIndex !== null && columns[x].sortIndex !== '') {
                item.sortIndex = columns[x].sortIndex;
            }

            if (columns[x].sortOrder !== undefined && columns[x].sortOrder !== null && columns[x].sortOrder !== '') {
                item.sortOrder = columns[x].sortOrder;
            }

            if (columns[x].cellTemplate !== undefined && columns[x].cellTemplate !== null) {
                item.cellTemplate = columns[x].cellTemplate;
            }

            dataColumns.push(item);
        }
    }

    return dataColumns;
}

function getStatusBadge(value) {
    if (!value) return '<span class="badge bg-secondary rounded px-2 py-1" style="font-size:0.75em;">No Data</span>';
    switch (value.toString().toLowerCase()) {
        case 'good': return '<span class="badge bg-success rounded px-2 py-1" style="font-size:0.75em;">Good</span>';
        case 'warning': return '<span class="badge bg-warning text-dark rounded px-2 py-1" style="font-size:0.75em;">Warning</span>';
        case 'danger': return '<span class="badge bg-danger rounded px-2 py-1" style="font-size:0.75em;">Danger</span>';
        case 'not applicable': return '<span class="badge bg-info rounded px-2 py-1" style="font-size:0.75em;">Not Applicable</span>';
        default: return '<span class="badge bg-secondary rounded px-2 py-1" style="font-size:0.75em;">No Data</span>';
    }
}

function getRiskStatusBadge(value) {
    if (!value) return '<span class="badge bg-secondary rounded px-2 py-1" style="font-size:0.75em;">No Data</span>';
    switch (value.toString().toLowerCase()) {
        case 'low': return '<span class="badge bg-success rounded px-2 py-1" style="font-size:0.75em;">Low</span>';
        case 'medium': return '<span class="badge bg-warning text-dark rounded px-2 py-1" style="font-size:0.75em;">Medium</span>';
        case 'medium high': return '<span class="badge rounded px-2 py-1" style="font-size:0.75em;background-color:#fd7e14;color:#fff;">Medium High</span>';
        case 'high': return '<span class="badge bg-danger rounded px-2 py-1" style="font-size:0.75em;">High</span>';
        default: return '<span class="badge bg-secondary rounded px-2 py-1" style="font-size:0.75em;">No Data</span>';
    }
}

function loadDxDataGridReadOnly(componentId, controllerName, actionName, columns) {
    var dataColumns = renderColumnsReadOnly(columns);

    $(() => {
        //JS PDF
        window.jsPDF = window.jspdf.jsPDF;

        function isNotEmpty(value) {
            return value !== undefined && value !== null && value !== '';
        }

        const store = new DevExpress.data.CustomStore({
            key: columns[0].name,
            load(loadOptions) {
                const deferred = $.Deferred();
                const args = {};
                [
                    'skip',
                    'take',
                    'requireTotalCount',
                    'requireGroupCount',
                    'sort',
                    'filter',
                    'totalSummary',
                    'group',
                    'groupSummary',
                ].forEach((i) => {
                    if (i in loadOptions && isNotEmpty(loadOptions[i])) {
                        args[i] = JSON.stringify(loadOptions[i]);
                    }
                });
                $.ajax({
                    url: url,
                    dataType: 'json',
                    contentType: "application/json; charset=utf-8",
                    data: args,
                    success(result) {
                        deferred.resolve(result.data, {
                            totalCount: result.totalCount,
                            summary: result.summary,
                            groupCount: result.groupCount,
                        });
                    }
                });

                return deferred.promise();
            },
        });

        var url = baseUrl + "/" + controllerName + "/" + actionName;

        const dataGrid = $('#' + componentId).dxDataGrid({
            dataSource: store,
            showColumnLines: true,
            showRowLines: true,
            rowAlternationEnabled: true,
            showBorders: true,
            filterRow: {
                visible: false,
            },
            headerFilter: {
                visible: false,
                allowSearch: false
            },
            groupPanel: {
                visible: true,
            },
            remoteOperations: true,
            paging: {
                pageSize: 10,
            },
            showBorders: true,
            columnAutoWidth: true,
            allowColumnResizing: true,
            scrolling: {
                mode: "standard",
                useNative: true,
                showScrollbar: "onScroll"
            },
            loadPanel: {
                enabled: true,
                text: "Loading data..."
            },
            pager: {
                visible: true,
                showPageSizeSelector: true,
                allowedPageSizes: [10, 50, 100],
                showNavigationButtons: true,
                showInfo: true
            },
            onEditorPreparing: prepareBooleanFilterEditor,
            onContentReady: function (e) {
                var index = DevExpress.localization.formatNumber(e.component.pageIndex() + 1, ",##0.###");
                var count = DevExpress.localization.formatNumber(e.component.pageCount(), ",##0.###");
                var total = DevExpress.localization.formatNumber(e.component.totalCount(), ",##0.###");
                e.component.option("pager.infoText", "Page " + index + " of " + count + " (" + total + " items)");
            },
            columns: dataColumns,
        }).dxDataGrid('instance');

        $('#export_pdf_dxgrid').dxButton({
            onClick: function (e) {
                const doc = new jsPDF();
                DevExpress.pdfExporter.exportDataGrid({
                    jsPDFDocument: doc,
                    component: dataGrid
                }).then(function () {
                    doc.save('Export.pdf');
                });
                e.cancel = true;
            }
        });

        $('#export_excel_dxgrid').dxButton({
            onClick: function (e) {
                const workbook = new ExcelJS.Workbook();
                const worksheet = workbook.addWorksheet('Sheet1');

                DevExpress.excelExporter.exportDataGrid({
                    component: dataGrid,
                    worksheet,
                    autoFilterEnabled: true,
                }).then(() => {
                    workbook.xlsx.writeBuffer().then((buffer) => {
                        saveAs(new Blob([buffer], { type: 'application/octet-stream' }), 'Export.xlsx');
                    });
                });
                e.cancel = true;
            }
        });
    });
}

function renderColumnsReadOnly(columns) {
    var dataColumns = [];
    for (let x = 0; x < columns.length; x++) {
        if (x == 0) {
            key = columns[x].name;
        }
        else {
            var item = {};

            item = {
                dataField: columns[x].name,
                dataType: columns[x].type,
                allowSearch: false,
                allowHeaderFiltering: false,
                allowGrouping: false,
                allowSorting: false,
            };
            item = applyBooleanColumnOptions(item, columns[x]);

            if (columns[x].name.toLowerCase() == "status") {
                item = {
                    dataField: columns[x].name,
                    dataType: columns[x].type,
                    cellTemplate(container, items) {
                        const { data } = items;
                        var appendDiv = $('<div>');
                        var htmlRender = "";
                        if (data.Status.toLowerCase() == "on") {
                            htmlRender = '<span class="badge rounded-pill badge-light-success" text-capitalized=""> ON</span>';
                        }
                        else {
                            htmlRender = '<span class="badge rounded-pill badge-light-danger" text-capitalized=""> OFF</span>';
                        }
                        appendDiv = appendDiv.append($(htmlRender)).appendTo(container);
                    }
                };
            }

            if (columns[x].name.toLowerCase() == "achievement") {
                item = {
                    dataField: columns[x].name,
                    dataType: columns[x].type,
                    cellTemplate(container, items) {
                        const { data } = items;
                        var appendDiv = $('<div>');
                        var htmlRender = "";
                        if (data.Achievement < 95) {
                            htmlRender = '<span class="badge rounded-pill badge bg-danger" text-capitalized="">' + data.Achievement + '</span>';
                        }
                        else if (data.Achievement >= 95 && data.Achievement < 100) {
                            htmlRender = '<span class="badge rounded-pill badge bg-warning" text-capitalized="">' + data.Achievement + '</span>';
                        }
                        else if (data.Achievement >= 100) {
                            htmlRender = '<span class="badge rounded-pill badge bg-success" text-capitalized="">' + data.Achievement + '</span>';
                        }
                        appendDiv = appendDiv.append($(htmlRender)).appendTo(container);
                    }
                };
            }

            if (columns[x].name.toLowerCase() == "approvalstatus") {
                item = {
                    dataField: columns[x].name,
                    dataType: columns[x].type,
                    cellTemplate(container, items) {
                        const { data } = items;
                        var appendDiv = $('<div>');
                        var htmlRender = "";
                        if (data.ApprovalStatus == "approved") {
                            htmlRender = '<span class="badge rounded-pill badge-light-success" text-capitalized=""> APPROVED</span>';
                        }
                        else if (data.ApprovalStatus == "revise") {
                            htmlRender = '<span class="badge rounded-pill badge-light-danger" text-capitalized=""> REJECT</span>';
                        }
                        else if (data.ApprovalStatus == "request") {
                            htmlRender = '<span class="badge rounded-pill badge-light-warning" text-capitalized=""> REQUEST</span>';
                        } else if (data.ApprovalStatus == "verified") {
                            htmlRender = '<span class="badge rounded-pill badge-light-info" text-capitalized=""> VERIFIED</span>';
                        } else if (data.ApprovalStatus == "running") {
                            htmlRender = '<span class="badge rounded-pill badge-light-success" text-capitalized=""> RUNNING</span>';
                        } else if (data.ApprovalStatus == "cancel") {
                            htmlRender = '<span class="badge rounded-pill badge-light-danger" text-capitalized=""> CANCEL</span>';
                        } else if (data.ApprovalStatus == "closed") {
                            htmlRender = '<span class="badge rounded-pill badge-light-success" text-capitalized=""> CLOSED</span>';
                        }
                        appendDiv = appendDiv.append($(htmlRender)).appendTo(container);
                    }
                };
            }

            if (columns[x].name.toLowerCase() == "projectpriority") {
                item = {
                    dataField: columns[x].name,
                    dataType: columns[x].type,
                    cellTemplate(container, items) {
                        const { data } = items;
                        var appendDiv = $('<div>');
                        var htmlRender = "";
                        if (data.ProjectPriority == "high") {
                            htmlRender = '<span class="badge rounded-pill badge-light-danger" text-capitalized=""> HIGH</span>';
                        }
                        else if (data.ProjectPriority == "medium") {
                            htmlRender = '<span class="badge rounded-pill badge-light-primary" text-capitalized=""> MEDIUM</span>';
                        }
                        else if (data.ProjectPriority == "low") {
                            htmlRender = '<span class="badge rounded-pill badge-light-success" text-capitalized=""> LOW</span>';
                        }
                        appendDiv = appendDiv.append($(htmlRender)).appendTo(container);
                    }
                };
            }

            if (columns[x].name.toLowerCase() == "resourcetype") {
                item = {
                    dataField: columns[x].name,
                    dataType: columns[x].type,
                    cellTemplate(container, items) {
                        const { data } = items;
                        var appendDiv = $('<div>');
                        var htmlRender = "";
                        if (data.ResourceType == "internal") {
                            htmlRender = '<span class="badge rounded-pill badge-light-success" text-capitalized=""> INTERNAL</span>';
                        }
                        else if (data.ResourceType == "external") {
                            htmlRender = '<span class="badge rounded-pill badge-light-primary" text-capitalized=""> EXTERNAL</span>';
                        }
                        appendDiv = appendDiv.append($(htmlRender)).appendTo(container);
                    }
                };
            }

            if (columns[x].type.toLowerCase() == "date") {
                item.format = "yyyy-MM-dd";
            }

            if (columns[x].type.toLowerCase() == "datetime") {
                item.format = "yyyy-MM-dd HH:mm";
            }

            if (columns[x].type.toLowerCase() == "currency" || columns[x].type.toLowerCase() == "number" || columns[x].type.toLowerCase() == "double") {
                item.format = ",##0.##";
            }

            if (columns[x].caption !== undefined && columns[x].caption !== null && columns[x].caption !== '') {
                item.caption = columns[x].caption;
            }

            if (columns[x].sortIndex !== undefined && columns[x].sortIndex !== null && columns[x].sortIndex !== '') {
                item.sortIndex = columns[x].sortIndex;
            }

            if (columns[x].sortOrder !== undefined && columns[x].sortOrder !== null && columns[x].sortOrder !== '') {
                item.sortOrder = columns[x].sortOrder;
            }

            dataColumns.push(item);
        }
    }

    return dataColumns;
}
